use strict;use warnings;use JSON::PP;use Digest::SHA qw(sha256_hex);use File::Basename qw(dirname);chdir dirname(__FILE__).'/..' or die $!;
my @results;for my $p(qw(review/preview.html review/contact-sheet.svg)){open my $f,'<',$p or die $!;local $/;my $s=<$f>;my %ids; $ids{$_}++ for $s=~/\bid="([^"]+)"/g;my @duplicates=grep{$ids{$_}>1}keys %ids;my @refs=($s=~/url\(#([^\)]+)\)/g,$s=~/(?:xlink:)?href=["']#([^"']+)["']/g);my @broken=grep{!exists $ids{$_}}@refs;die 'duplicate or broken reference' if @duplicates || @broken;push @results,{path=>$p,bytes=>length($s),sha256=>sha256_hex($s),uniqueIds=>scalar(keys %ids),fragmentReferences=>scalar @refs,duplicateIds=>\@duplicates,brokenReferences=>\@broken};}open my $o,'>','review/preview-reference-check.json';print $o JSON::PP->new->canonical->pretty->encode({method=>'static attribute/reference scan; not XML parsing or rendering',files=>\@results});print JSON::PP->new->encode(\@results);
